import { requirePageOwner } from "@/server/auth/page-owner";
export const dynamic = "force-dynamic";
import type { Metadata } from "next";
import { PublishReview } from "@/features/admin/publish-review";
import { approvedPublication } from "@/content/approved-publication";
import { readPublicPublication, readPublicationHistory } from "@/server/content/publish";
import styles from "@/app/admin/admin.module.css";

export const metadata: Metadata = {
  title: "Publish Review & Rollback | YOR WORLD Administration",
  robots: { index: false, follow: false },
};

export default async function AdminPublishPage() {
  await requirePageOwner();
  const publication = await readPublicPublication() ?? approvedPublication;
  const initialHistory = await readPublicationHistory();

  return (
    <div>
      <header>
        <h1 className={styles.title}>Publication Review & Rollback</h1>
        <p className={styles.subtitle}>
          Pre-flight evidence and media checks, optimistic concurrency publication, and authoritative rollback.
        </p>
      </header>

      <PublishReview
        initialPublication={publication}
        initialHistory={initialHistory}
      />
    </div>
  );
}

import { verifyOwner, createAuthErrorResponse } from "@/server/auth/require-owner";
import {
  publishRevision,
  readPublicPublication,
  readPublicationHistory,
} from "@/server/content/publish";
import { RevisionConflictError, ContentValidationError } from "@/server/content/revisions";
import { MediaValidationError } from "@/server/media/validate-upload";

export const dynamic = "force-dynamic";

export async function GET(request: Request) {
  const result = await verifyOwner(request);
  if (!result.ok) {
    return createAuthErrorResponse(result);
  }

  try {
  const active = await readPublicPublication();
  if (!active) return Response.json({ error: "Publication storage is unavailable." },{ status: 503 });
  const history = await readPublicationHistory();

  return Response.json(
    {
      currentRevision: active.revision,
      activePublication: active,
      history,
      authorizedActor: result.context.userId,
    },
    {
      headers: {
        "Cache-Control": "no-store",
        Vary: "Authorization, Cookie",
      },
    }
  );
  } catch {
    return Response.json({ error: "Private storage is temporarily unavailable." },{ status: 503,headers: { "Cache-Control": "no-store, private",Vary: "Authorization, Cookie" } });
  }

}

export async function POST(request: Request) {
  const result = await verifyOwner(request);
  if (!result.ok) {
    return createAuthErrorResponse(result);
  }

  try {
    const body = await request.json();

    if (typeof body.expectedRevision !== "number") {
      return Response.json(
        { error: "expectedRevision (number) is required" },
        { status: 422 }
      );
    }

    const publication = await publishRevision(
      {
        expectedRevision: body.expectedRevision,
        projectId: body.projectId,
      },
      result.context
    );

    return Response.json(
      {
        success: true,
        action: "publication_published",
        publication,
        actor: result.context.userId,
      },
      { status: 200 }
    );
  } catch (err) {
    if (err instanceof RevisionConflictError) {
      return Response.json(
        { error: err.message, code: err.code },
        { status: 409 }
      );
    }
    if (err instanceof ContentValidationError || err instanceof MediaValidationError) {
      return Response.json(
        { error: err.message, code: "UNPROCESSABLE_ENTITY" },
        { status: 422 }
      );
    }
    return Response.json(
      { error: "Private storage is temporarily unavailable." },
      { status: 503 }
    );
  }
}

import { z } from "zod";

const text = z.string().min(1);
const httpsUrl = z.url({ protocol: /^https$/ });
const timestamp = z.iso.datetime({ offset: true });

export const ProjectIdSchema = z.enum(["candidatex", "helios", "zenith", "ai-vs-real", "talks"]);
export type ProjectId = z.infer<typeof ProjectIdSchema>;

export const EvidenceStatusSchema = z.enum(["verified", "unknown", "not-measured", "not-applicable"]);
export type EvidenceStatus = z.infer<typeof EvidenceStatusSchema>;

export const EvidenceRefSchema = z.strictObject({
  id: text,
  kind: z.enum(["repository", "deployment", "measurement", "document"]),
  url: httpsUrl.nullable(),
  checkedAt: timestamp.nullable(),
  status: EvidenceStatusSchema,
  note: z.string(),
});
export type EvidenceRef = z.infer<typeof EvidenceRefSchema>;

export const ContentSectionSchema = z.strictObject({
  id: text,
  heading: text,
  blocks: z.array(z.discriminatedUnion("type", [
    z.strictObject({ type: z.literal("paragraph"), text }),
    z.strictObject({ type: z.literal("image"), mediaId: text, alt: z.string(), caption: z.string() }),
    z.strictObject({ type: z.literal("list"), items: z.array(text) }),
    z.strictObject({ type: z.literal("code"), language: text, text }),
  ])),
});
export type ContentSection = z.infer<typeof ContentSectionSchema>;

export const PublishedProjectSchema = z.strictObject({
  id: ProjectIdSchema,
  slug: z.string().regex(/^[a-z0-9]+(?:-[a-z0-9]+)*$/),
  title: text,
  summary: text,
  contribution: text,
  sections: z.array(ContentSectionSchema),
  links: z.array(z.strictObject({ label: text, url: httpsUrl, checkedAt: timestamp })),
  evidence: z.array(EvidenceRefSchema),
  revision: z.number().int().positive(),
});
export type PublishedProject = z.infer<typeof PublishedProjectSchema>;

export const PublicationSchema = z.strictObject({
  revision: z.number().int().positive(),
  publishedAt: timestamp,
  projects: z.array(PublishedProjectSchema),
  assetManifestRevision: text,
});
export type Publication = z.infer<typeof PublicationSchema>;

// These are structural boundary schemas. A2/A4 must additionally verify evidence,
// approved media, unique IDs/slugs, and owner authorization before publication.

"use client";

/**
 * YOR WORLD Milestone A4: Structured Project Editor
 *
 * Provides owner-managed structured content editing for projects, sections,
 * evidence records, and media attachments with optimistic concurrency control.
 */

import { useState } from "react";
import type {
  ProjectId,
  PublishedProject,
  ContentSection,
  EvidenceRef,
  EvidenceStatus,
} from "@/contracts/content";
import styles from "@/app/admin/admin.module.css";

interface ProjectEditorProps {
  initialProjects: PublishedProject[];
}

export function ProjectEditor({ initialProjects }: ProjectEditorProps) {
  const [projects, setProjects] = useState<PublishedProject[]>(initialProjects);
  const [selectedId, setSelectedId] = useState<ProjectId>(
    initialProjects[0]?.id || "ai-vs-real"
  );
  const [feedback, setFeedback] = useState<{
    type: "success" | "error" | "warning";
    message: string;
  } | null>(null);
  const [saving, setSaving] = useState(false);

  const currentProject = projects.find((p) => p.id === selectedId) ?? projects[0];
  const [expectedRevision, setExpectedRevision] = useState<number>(
    currentProject?.revision ?? 1
  );

  function handleProjectChange(id: ProjectId) {
    setSelectedId(id);
    const target = projects.find((p) => p.id === id);
    if (target) {
      setExpectedRevision(target.revision);
    }
    setFeedback(null);
  }

  function updateField<K extends keyof PublishedProject>(field: K, value: PublishedProject[K]) {
    setProjects((prev) =>
      prev.map((p) => (p.id === selectedId ? { ...p, [field]: value } : p))
    );
  }

  // Section modifiers
  function addSection() {
    if (!currentProject) return;
    const newSection: ContentSection = {
      id: `sec-${Date.now()}`,
      heading: "New Section",
      blocks: [{ type: "paragraph", text: "New section content." }],
    };
    updateField("sections", [...currentProject.sections, newSection]);
  }

  function updateSectionHeading(sectionIndex: number, heading: string) {
    if (!currentProject) return;
    const updated = [...currentProject.sections];
    const prev = updated[sectionIndex];
    if (prev) {
      updated[sectionIndex] = { ...prev, heading };
      updateField("sections", updated);
    }
  }

  function removeSection(sectionIndex: number) {
    if (!currentProject) return;
    const updated = currentProject.sections.filter((_, idx) => idx !== sectionIndex);
    updateField("sections", updated);
  }

  // Link modifiers
  function addLink() {
    if (!currentProject) return;
    const newLink = {
      label: "Documentation",
      url: "https://example.com/docs",
      checkedAt: new Date().toISOString(),
    };
    updateField("links", [...currentProject.links, newLink]);
  }

  function updateLink(index: number, label: string, url: string) {
    if (!currentProject) return;
    const updated = [...currentProject.links];
    const prev = updated[index];
    if (prev) {
      updated[index] = { ...prev, label, url };
      updateField("links", updated);
    }
  }

  function removeLink(index: number) {
    if (!currentProject) return;
    const updated = currentProject.links.filter((_, idx) => idx !== index);
    updateField("links", updated);
  }

  // Evidence modifiers
  function addEvidence() {
    if (!currentProject) return;
    const newEvidence: EvidenceRef = {
      id: `ev-${Date.now()}`,
      kind: "document",
      url: "https://example.com/evidence",
      checkedAt: new Date().toISOString(),
      status: "verified",
      note: "Verified documentation record.",
    };
    updateField("evidence", [...currentProject.evidence, newEvidence]);
  }

  function updateEvidence<K extends keyof EvidenceRef>(index: number, field: K, val: EvidenceRef[K]) {
    if (!currentProject) return;
    const updated = [...currentProject.evidence];
    const prev = updated[index];
    if (prev) {
      updated[index] = { ...prev, [field]: val };
      updateField("evidence", updated);
    }
  }

  function removeEvidence(index: number) {
    if (!currentProject) return;
    const updated = currentProject.evidence.filter((_, idx) => idx !== index);
    updateField("evidence", updated);
  }

  async function handleSaveDraft() {
    if (!currentProject) return;
    setSaving(true);
    setFeedback(null);

    try {
      const response = await fetch("/api/admin/projects", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          projectId: currentProject.id,
          expectedRevision,
          project: currentProject,
        }),
      });

      const data = await response.json();

      if (response.status === 409) {
        setFeedback({
          type: "error",
          message: `Revision Conflict (409): ${data.error || "Draft revision mismatch. Another session modified this draft."}`,
        });
      } else if (response.status === 422) {
        setFeedback({
          type: "error",
          message: `Validation Error (422): ${data.error || "Invalid content or unverified evidence."}`,
        });
      } else if (!response.ok) {
        setFeedback({
          type: "error",
          message: `Save failed (${response.status}): ${data.error || "Unknown server error."}`,
        });
      } else {
        const newRev = data.draftRevision;
        setExpectedRevision(newRev);
        setProjects((prev) =>
          prev.map((p) => (p.id === currentProject.id ? { ...p, revision: newRev } : p))
        );
        setFeedback({
          type: "success",
          message: `Draft saved successfully! Updated draft revision: ${newRev}`,
        });
      }
    } catch (err) {
      setFeedback({
        type: "error",
        message: err instanceof Error ? err.message : "Network error saving draft",
      });
    } finally {
      setSaving(false);
    }
  }

  if (!currentProject) {
    return <div>No projects available for editing.</div>;
  }

  return (
    <div style={{ marginTop: "1.5rem" }}>
      {/* Project selector & revision header */}
      <div className={styles.sectionBox} style={{ display: "flex", flexWrap: "wrap", alignItems: "center", justifyContent: "space-between", gap: "1rem" }}>
        <div>
          <label htmlFor="project-select" className={styles.label} style={{ marginRight: "0.5rem" }}>
            Select Project:
          </label>
          <select
            id="project-select"
            value={selectedId}
            onChange={(e) => handleProjectChange(e.target.value as ProjectId)}
            className={styles.input}
            style={{ width: "auto", display: "inline-block" }}
          >
            {projects.map((p) => (
              <option key={p.id} value={p.id}>
                {p.title} ({p.id})
              </option>
            ))}
          </select>
        </div>

        <div style={{ display: "flex", alignItems: "center", gap: "1rem" }}>
          <span className={`${styles.badge} ${styles.badgeSuccess}`}>
            Current Draft Revision: {currentProject.revision}
          </span>
          <div style={{ display: "flex", alignItems: "center", gap: "0.5rem" }}>
            <label htmlFor="expected-rev" className={styles.label}>
              Expected Rev:
            </label>
            <input
              id="expected-rev"
              type="number"
              value={expectedRevision}
              onChange={(e) => setExpectedRevision(Number(e.target.value))}
              className={styles.input}
              style={{ width: "80px", padding: "0.3rem 0.5rem" }}
            />
          </div>
        </div>
      </div>

      {feedback && (
        <div
          role="alert"
          className={`${styles.feedbackBox} ${
            feedback.type === "success"
              ? styles.feedbackSuccess
              : feedback.type === "warning"
              ? styles.feedbackWarning
              : styles.feedbackError
          }`}
        >
          {feedback.message}
        </div>
      )}

      {/* Basic metadata */}
      <div className={styles.sectionBox}>
        <h3 style={{ marginBottom: "1rem" }}>Project Overview & Summary</h3>
        <div className={styles.field} style={{ marginBottom: "1rem" }}>
          <label htmlFor="proj-title" className={styles.label}>
            Title
          </label>
          <input
            id="proj-title"
            className={styles.input}
            value={currentProject.title}
            onChange={(e) => updateField("title", e.target.value)}
          />
        </div>

        <div className={styles.field} style={{ marginBottom: "1rem" }}>
          <label htmlFor="proj-summary" className={styles.label}>
            Summary
          </label>
          <textarea
            id="proj-summary"
            className={styles.input}
            rows={3}
            value={currentProject.summary}
            onChange={(e) => updateField("summary", e.target.value)}
          />
        </div>

        <div className={styles.field}>
          <label htmlFor="proj-contrib" className={styles.label}>
            Contribution
          </label>
          <textarea
            id="proj-contrib"
            className={styles.input}
            rows={3}
            value={currentProject.contribution}
            onChange={(e) => updateField("contribution", e.target.value)}
          />
        </div>
      </div>

      {/* Content Sections */}
      <div className={styles.sectionBox}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "1rem" }}>
          <h3>Structured Content Sections ({currentProject.sections.length})</h3>
          <button type="button" onClick={addSection} className={styles.buttonSecondary}>
            + Add Section
          </button>
        </div>

        {currentProject.sections.map((sec, secIdx) => (
          <div key={sec.id || secIdx} style={{ border: "1px solid var(--color-line)", padding: "1rem", borderRadius: "6px", marginBottom: "1rem" }}>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "0.75rem" }}>
              <input
                aria-label={`Section ${secIdx + 1} Heading`}
                value={sec.heading}
                onChange={(e) => updateSectionHeading(secIdx, e.target.value)}
                className={styles.input}
                style={{ fontWeight: 600, maxWidth: "400px" }}
              />
              <button
                type="button"
                onClick={() => removeSection(secIdx)}
                className={styles.buttonDanger}
              >
                Delete Section
              </button>
            </div>

            <div style={{ fontSize: "0.85rem", color: "var(--color-muted)" }}>
              {sec.blocks.map((b, bIdx) => (
                <div key={bIdx} style={{ padding: "0.35rem 0" }}>
                  Block {bIdx + 1} ({b.type}): {b.type === "paragraph" || b.type === "code" ? b.text.slice(0, 60) + "..." : b.type === "image" ? `Image ID: ${b.mediaId}` : `List (${b.items.length} items)`}
                </div>
              ))}
            </div>
          </div>
        ))}
      </div>

      {/* External Links */}
      <div className={styles.sectionBox}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "1rem" }}>
          <h3>External Links ({currentProject.links.length})</h3>
          <button type="button" onClick={addLink} className={styles.buttonSecondary}>
            + Add Link
          </button>
        </div>

        {currentProject.links.map((link, idx) => (
          <div key={idx} style={{ display: "flex", gap: "0.75rem", marginBottom: "0.5rem" }}>
            <input
              placeholder="Label"
              value={link.label}
              onChange={(e) => updateLink(idx, e.target.value, link.url)}
              className={styles.input}
              style={{ flex: "1" }}
            />
            <input
              placeholder="https://..."
              value={link.url}
              onChange={(e) => updateLink(idx, link.label, e.target.value)}
              className={styles.input}
              style={{ flex: "2" }}
            />
            <button type="button" onClick={() => removeLink(idx)} className={styles.buttonDanger}>
              Remove
            </button>
          </div>
        ))}
      </div>

      {/* Evidence Records */}
      <div className={styles.sectionBox}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "1rem" }}>
          <h3>Evidence Records ({currentProject.evidence.length})</h3>
          <button type="button" onClick={addEvidence} className={styles.buttonSecondary}>
            + Add Evidence
          </button>
        </div>

        {currentProject.evidence.map((ev, idx) => (
          <div key={idx} style={{ border: "1px solid var(--color-line)", padding: "0.75rem", borderRadius: "6px", marginBottom: "0.75rem" }}>
            <div style={{ display: "flex", gap: "0.5rem", marginBottom: "0.5rem" }}>
              <input
                placeholder="Evidence ID"
                value={ev.id}
                onChange={(e) => updateEvidence(idx, "id", e.target.value)}
                className={styles.input}
                style={{ flex: "1" }}
              />
              <select
                value={ev.status}
                onChange={(e) => updateEvidence(idx, "status", e.target.value as EvidenceStatus)}
                className={styles.input}
                style={{ width: "160px" }}
              >
                <option value="verified">verified</option>
                <option value="unknown">unknown</option>
                <option value="not-measured">not-measured</option>
                <option value="not-applicable">not-applicable</option>
              </select>
              <button type="button" onClick={() => removeEvidence(idx)} className={styles.buttonDanger}>
                Remove
              </button>
            </div>
            <input
              placeholder="Evidence note..."
              value={ev.note}
              onChange={(e) => updateEvidence(idx, "note", e.target.value)}
              className={styles.input}
            />
          </div>
        ))}
      </div>

      {/* Save Draft Action */}
      <div className={styles.actionRow}>
        <button
          type="button"
          onClick={handleSaveDraft}
          disabled={saving}
          className={styles.button}
          style={{ width: "auto", minWidth: "200px" }}
        >
          {saving ? "Saving Draft..." : "Save Draft Revision"}
        </button>
      </div>
    </div>
  );
}

"use client";

/**
 * YOR WORLD Milestone A4: Publish Review & Rollback Manager
 *
 * Provides pre-flight review, publication validation checks, optimistic concurrency
 * publication execution, publication history auditing, and safe rollback with asset verification.
 */

import { useState } from "react";
import type { Publication } from "@/contracts/content";
import styles from "@/app/admin/admin.module.css";

export interface HistoryItem {
  revision: number;
  actor: string;
  publishedAt: string;
  action: "publish" | "rollback";
  targetRevision?: number;
}

interface PublishReviewProps {
  initialPublication: Publication;
  initialHistory: HistoryItem[];
}

export function PublishReview({
  initialPublication,
  initialHistory,
}: PublishReviewProps) {
  const [publication, setPublication] = useState<Publication>(initialPublication);
  const [history, setHistory] = useState<HistoryItem[]>(initialHistory);
  const [expectedRevision, setExpectedRevision] = useState<number>(
    initialPublication.revision
  );
  const [feedback, setFeedback] = useState<{
    type: "success" | "error" | "warning";
    message: string;
  } | null>(null);
  const [busy, setBusy] = useState(false);

  async function handlePublish() {
    setBusy(true);
    setFeedback(null);

    try {
      const response = await fetch("/api/admin/publish", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ expectedRevision }),
      });

      const data = await response.json();

      if (response.status === 409) {
        setFeedback({
          type: "error",
          message: `Stale Revision Conflict (409): ${data.error || "The expected publication revision does not match current state. Refresh before publishing."}`,
        });
      } else if (response.status === 422) {
        setFeedback({
          type: "error",
          message: `Validation Error (422): ${data.error || "Publication rejected due to unapproved media or invalid content."}`,
        });
      } else if (!response.ok) {
        setFeedback({
          type: "error",
          message: `Publication failed (${response.status}): ${data.error || "Unknown server error"}`,
        });
      } else {
        const nextPub: Publication = data.publication;
        setPublication(nextPub);
        setExpectedRevision(nextPub.revision);
        setHistory((prev) => [
          ...prev,
          {
            revision: nextPub.revision,
            actor: data.actor || "owner",
            publishedAt: nextPub.publishedAt,
            action: "publish",
          },
        ]);
        setFeedback({
          type: "success",
          message: `Publication Revision ${nextPub.revision} successfully published! Public snapshot updated.`,
        });
      }
    } catch (err) {
      setFeedback({
        type: "error",
        message: err instanceof Error ? err.message : "Network error publishing revision",
      });
    } finally {
      setBusy(false);
    }
  }

  async function handleRollback(targetRev: number) {
    if (
      !confirm(
        `Are you sure you want to rollback to publication revision ${targetRev}? All assets referenced in revision ${targetRev} will be validated before publication.`
      )
    ) {
      return;
    }

    setBusy(true);
    setFeedback(null);

    try {
      const response = await fetch("/api/admin/rollback", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ targetRevision: targetRev }),
      });

      const data = await response.json();

      if (response.status === 422) {
        setFeedback({
          type: "error",
          message: `Rollback Rejected (422): ${data.error || "Missing or unapproved assets detected for target revision."}`,
        });
      } else if (!response.ok) {
        setFeedback({
          type: "error",
          message: `Rollback failed (${response.status}): ${data.error || "Unknown server error"}`,
        });
      } else {
        const nextPub: Publication = data.publication;
        setPublication(nextPub);
        setExpectedRevision(nextPub.revision);
        setHistory((prev) => [
          ...prev,
          {
            revision: nextPub.revision,
            actor: data.actor || "owner",
            publishedAt: nextPub.publishedAt,
            action: "rollback",
            targetRevision: targetRev,
          },
        ]);
        setFeedback({
          type: "success",
          message: `Rollback successful! Restored revision ${targetRev} as new publication revision ${nextPub.revision}.`,
        });
      }
    } catch (err) {
      setFeedback({
        type: "error",
        message: err instanceof Error ? err.message : "Network error performing rollback",
      });
    } finally {
      setBusy(false);
    }
  }

  return (
    <div style={{ marginTop: "1.5rem" }}>
      {/* Current publication status overview */}
      <div className={styles.grid}>
        <div className={styles.card}>
          <h3>Active Publication</h3>
          <p className={styles.subtitle} style={{ margin: "var(--space-2) 0" }}>
            Current Revision: <span className={`${styles.badge} ${styles.badgeSuccess}`}>r{publication.revision}</span>
          </p>
          <p className={styles.subtitle}>
            Published: {new Date(publication.publishedAt).toLocaleString()}
          </p>
        </div>

        <div className={styles.card}>
          <h3>Published Projects</h3>
          <p className={styles.subtitle} style={{ margin: "var(--space-2) 0" }}>
            Total Active: <span className={styles.badge}>{publication.projects.length} Projects</span>
          </p>
          <p className={styles.subtitle}>
            Slugs: {publication.projects.map((p) => p.slug).join(", ")}
          </p>
        </div>

        <div className={styles.card}>
          <h3>Pre-Flight Checklist</h3>
          <ul style={{ paddingLeft: "1.2rem", fontSize: "0.85rem", color: "var(--color-muted)", margin: "0.5rem 0" }}>
            <li>✓ Strict schema validation</li>
            <li>✓ 100% verified evidence (zero unknown)</li>
