  setActivePublicationSnapshot(approvedPublication);
  simulateCacheRefreshFailure = false;
}

/**
 * Validates complete publication content integrity:
 * - Structural schema checks
 * - Safe HTTPS links
 * - Verified evidence (no unknown claims)
 * - Approved media assets
 */
export async function validatePublicationContent(publication: Publication, transaction?: QueryableDb): Promise<void> {
  const parsed = PublicationSchema.safeParse(publication);
  if (!parsed.success) {
    throw new ContentValidationError(
      `Publication schema invalid: ${parsed.error.issues.map((i) => `${i.path.join(".")}: ${i.message}`).join(", ")}`
    );
  }

  const seenSlugs = new Set<string>();
  const seenIds = new Set<string>();

  for (const project of publication.projects) {
    if (seenSlugs.has(project.slug)) {
      throw new ContentValidationError(`Duplicate project slug '${project.slug}' in publication snapshot`);
    }
    seenSlugs.add(project.slug);

    if (seenIds.has(project.id)) {
      throw new ContentValidationError(`Duplicate project ID '${project.id}' in publication snapshot`);
    }
    seenIds.add(project.id);

    // Rule: Every published project must have verified evidence
    const verifiedEvidence = project.evidence.filter((e) => e.status === "verified");
    if (verifiedEvidence.length === 0) {
      throw new ContentValidationError(
        `Project '${project.slug}' has no verified evidence. Projects cannot be published without verifiable evidence.`
      );
    }

    // Rule: Rejection of unsupported claims
    for (const ev of project.evidence) {
      if (ev.status === "unknown") {
        throw new ContentValidationError(
          `Project '${project.slug}' contains unverified claim '${ev.id}' with status 'unknown'. Unsupported claims cannot enter public publication.`
        );
      }
      if (!ev.note || ev.note.trim().length === 0) {
        throw new ContentValidationError(
          `Project '${project.slug}' evidence '${ev.id}' is missing descriptive verification note.`
        );
      }
      if (ev.url) {
        try {
          const url = new URL(ev.url);
          if (url.protocol !== "https:") {
            throw new ContentValidationError(
              `Project '${project.slug}' evidence '${ev.id}' has insecure URL '${ev.url}'. Only https:// is permitted.`
            );
          }
        } catch (err) {
          if (err instanceof ContentValidationError) throw err;
          throw new ContentValidationError(`Project '${project.slug}' evidence '${ev.id}' has malformed URL '${ev.url}'.`);
        }
      }
    }

    // Rule: Safe external links
    for (const link of project.links) {
      try {
        const url = new URL(link.url);
        if (url.protocol !== "https:") {
          throw new ContentValidationError(
            `Project '${project.slug}' link '${link.label}' has insecure URL '${link.url}'. Only https:// is permitted.`
          );
        }
      } catch (err) {
        if (err instanceof ContentValidationError) throw err;
        throw new ContentValidationError(`Project '${project.slug}' link has malformed URL '${link.url}'.`);
      }
    }

    // Rule: Content sections & blocks
    for (const section of project.sections) {
      if (!section.heading || section.heading.trim().length === 0) {
        throw new ContentValidationError(`Project '${project.slug}' section '${section.id}' has empty heading.`);
      }
      if (section.blocks.length === 0) {
        throw new ContentValidationError(`Project '${project.slug}' section '${section.id}' has no content blocks.`);
      }
    }
  }

  // Rule: Check that all media assets referenced in sections are approved!
  await verifyPublicationAssets(publication, transaction);
}

/**
 * Simulates or handles cache refresh across public edge / ISR / in-memory layer.
 */
async function handleCacheRefresh(publication: Publication): Promise<{ refreshed: boolean; error?: string }> {
  if (simulateCacheRefreshFailure) {
    return {
      refreshed: false,
      error: "Simulated cache-refresh service timeout",
    };
  }

  try {
    setActivePublicationSnapshot(publication);
    return { refreshed: true };
  } catch (err) {
    return {
      refreshed: false,
      error: err instanceof Error ? err.message : "Cache refresh failed",
    };
  }
}

/**
 * Publishes a new revision of the portfolio publication snapshot.
 *
 * Enforces:
 * - Optimistic concurrency: stale expectedRevision -> 409
 * - Content and media validation -> 422
 * - Transactional history and snapshot recording
 * - Resilient cache refresh
 */
export async function publishRevision(
  input: {
    projectId?: ProjectId;
    expectedRevision: number;
    customProjects?: PublishedProject[];
  },
  actor: OwnerContext
): Promise<Publication & { cacheRefreshed?: boolean; cacheRefreshWarning?: string }> {
  if (!isDraftTestRegistryEnabled()) return publishDurable(input, actor);
  const currentRevision = activePublication.revision;

  // 1. Optimistic concurrency check
  if (currentRevision !== input.expectedRevision) {
    throw new RevisionConflictError(
      `Stale revision conflict: expected publication revision ${input.expectedRevision}, but current publication is revision ${currentRevision}. Refresh before publishing.`
    );
  }

  // 2. Prepare projects to publish
  let projectsToPublish: PublishedProject[];

  if (input.customProjects) {
    projectsToPublish = input.customProjects;
  } else {
    // Collect active drafts from draft registry
    const draftRegistry = getTestDraftRegistry();
    projectsToPublish = [];

    // Include all approved projects from drafts, excluding unpublished candidatex
    for (const [id, draft] of draftRegistry.entries()) {
      if (id === "candidatex") {
        continue;
      }
      projectsToPublish.push(draft.project);
    }
  }

  const nextRevision = currentRevision + 1;
  const now = new Date().toISOString();

  const nextPublication: Publication = {
    revision: nextRevision,
    publishedAt: now,
    projects: projectsToPublish,
    assetManifestRevision: `manifest-${now.slice(0, 10).replace(/-/g, "")}-r${nextRevision}`,
  };

  // 3. Validation gate: structural, links, evidence, and media approval (throws 422 if invalid)
  await validatePublicationContent(nextPublication);

  // 4. Record history & active snapshot (durable transaction)
  const historyEntry: PublicationHistoryEntry = {
    revision: nextRevision,
    snapshot: nextPublication,
    actor: actor.userId,
    publishedAt: now,
    action: "publish",
  };
  publicationHistory.push(historyEntry);
  activePublication = nextPublication;

  // 5. Cache-refresh handling (failure preserves durable DB revision)
  const cacheResult = await handleCacheRefresh(nextPublication);

  return {
    ...nextPublication,
    cacheRefreshed: cacheResult.refreshed,
    ...(cacheResult.error ? { cacheRefreshWarning: cacheResult.error } : {}),
  };
}

/**
 * Rolls back publication to a previously approved publication snapshot.
 *
 * Enforces:
 * - Target revision exists in publication history -> 422 / 404
 * - Referenced assets are verified to still exist and be approved -> 422
 * - Restores snapshot as a NEW incremented revision
 * - Records rollback in publication history and audit log
 */
export async function rollbackPublication(
  targetRevision: number,
  actor: OwnerContext
): Promise<Publication & { cacheRefreshed?: boolean; cacheRefreshWarning?: string }> {
  if (!isDraftTestRegistryEnabled()) return rollbackDurable(targetRevision, actor);
  // 1. Locate target revision in history
  const targetEntry = publicationHistory.find((entry) => entry.revision === targetRevision);
  if (!targetEntry) {
    throw new ContentValidationError(
      `Rollback rejected: target publication revision ${targetRevision} does not exist in publication history`
    );
  }

  const targetSnapshot = targetEntry.snapshot;

  // 2. Verify that all referenced assets in target snapshot are STILL available and approved
  await verifyPublicationAssets(targetSnapshot);

  // 3. Publish rollback as a NEW revision
  const newRevision = activePublication.revision + 1;
  const now = new Date().toISOString();

  const restoredPublication: Publication = {
    ...targetSnapshot,
    revision: newRevision,
    publishedAt: now,
  };

  const rollbackEntry: PublicationHistoryEntry = {
    revision: newRevision,
    snapshot: restoredPublication,
    actor: actor.userId,
    publishedAt: now,
    action: "rollback",
    targetRevision,
  };
  publicationHistory.push(rollbackEntry);
  activePublication = restoredPublication;

  // 4. Cache refresh
  const cacheResult = await handleCacheRefresh(restoredPublication);

  return {
    ...restoredPublication,
    cacheRefreshed: cacheResult.refreshed,
    ...(cacheResult.error ? { cacheRefreshWarning: cacheResult.error } : {}),
  };
}

/** Public reader accesses only approved published_content, never drafts or private media. */
export async function readPublicPublication(): Promise<Publication | null> {
  if (isDraftTestRegistryEnabled()) return activePublication;
  if (!hasPlatformDatabase()) return null;
  const db = await getPlatformDb();
  return readDurablePublication(db);
}

async function readDurablePublication(db: QueryableDb): Promise<Publication> {
  const rows = await db.query("SELECT payload FROM public.published_content ORDER BY revision DESC,published_at DESC LIMIT 1");
  return rows.rows[0] ? PublicationSchema.parse(rows.rows[0]["payload"]) : approvedPublication;
}

export async function readPublicationHistory(): Promise<PublicationHistoryEntry[]> {
  if (isDraftTestRegistryEnabled()) return getPublicationHistoryList();
  const db = await getPlatformDb();
  const result = await db.query(`SELECT h.revision,h.snapshot,h.actor,h.created_at,
    a.action,a.payload AS audit_payload FROM public.publication_history h
    LEFT JOIN public.audit_events a ON a.entity_type='publication' AND a.entity_id=h.revision::text
    AND a.action IN ('publication_published','publication_rollback') ORDER BY h.revision`);
  if (!result.rows.length) return [{ revision: approvedPublication.revision,snapshot: approvedPublication,
    actor: "accepted-static-baseline",publishedAt: approvedPublication.publishedAt,action: "publish" }];
  return result.rows.map((row) => ({ revision: Number(row["revision"]), snapshot: PublicationSchema.parse(row["snapshot"]),
    actor: String(row["actor"]), publishedAt: new Date(String(row["created_at"])).toISOString(),
    action: row["action"] === "publication_rollback" ? "rollback" : "publish",
    ...(row["action"] === "publication_rollback" ? { targetRevision: Number((row["audit_payload"] as Record<string,unknown>)["targetRevision"]) } : {}) }));
}

async function writeSnapshot(tx: QueryableDb, publication: Publication, actor: OwnerContext, targetRevision?: number) {
  // Record the accepted baseline once so the first deployment has a rollback target.
  const baseline = await tx.query("SELECT revision FROM public.publication_history WHERE revision=$1 LIMIT 1", [approvedPublication.revision]);
  if (!baseline.rows.length) await tx.query("INSERT INTO public.publication_history(revision,snapshot,actor) VALUES($1,$2,$3)", [approvedPublication.revision,JSON.stringify(approvedPublication),actor.userId]);
  await tx.query("INSERT INTO public.publication_history(revision,snapshot,actor) VALUES($1,$2,$3)", [publication.revision,JSON.stringify(publication),actor.userId]);
  await tx.query("INSERT INTO public.published_content(revision,payload) VALUES($1,$2)", [publication.revision,JSON.stringify(publication)]);
  await tx.query("INSERT INTO public.audit_events(actor,action,entity_type,entity_id,payload) VALUES($1,$2,'publication',$3,$4)",
    [actor.userId,targetRevision === undefined ? "publication_published" : "publication_rollback",String(publication.revision),JSON.stringify({ revision: publication.revision,...(targetRevision === undefined ? {} : { targetRevision }) })]);
}

async function publishDurable(input: { projectId?: ProjectId; expectedRevision: number; customProjects?: PublishedProject[] }, actor: OwnerContext) {
  const db = await getPlatformDb();
  if (!db.transaction) throw new Error("Transactional database is required.");
  const publication = await db.transaction(async (tx) => {
    await tx.query("SELECT pg_advisory_xact_lock(hashtext('yor-publication'))");
    const current = await readDurablePublication(tx);
    if (current.revision !== input.expectedRevision) throw new RevisionConflictError("Publication changed. Refresh before publishing.");
    const projects = input.customProjects ?? (await readDurableDrafts(tx)).filter((draft) => draft.projectId !== "candidatex").map((draft) => draft.project);
    // CandidateX cannot be added without a separately accepted content decision.
    if (projects.some((project) => project.id === "candidatex")) throw new ContentValidationError("CandidateX has no accepted public content decision.");
    const next: Publication = { revision: current.revision + 1,publishedAt: new Date().toISOString(),projects,
      assetManifestRevision: current.assetManifestRevision };
    await validatePublicationContent(next,tx);
    await writeSnapshot(tx,next,actor);
    return next;
  });
  const refreshed = await handleCacheRefresh(publication);
  return { ...publication,cacheRefreshed: refreshed.refreshed,...(refreshed.error ? { cacheRefreshWarning: refreshed.error } : {}) };
}

async function rollbackDurable(targetRevision: number, actor: OwnerContext) {
  const db = await getPlatformDb();
  if (!db.transaction) throw new Error("Transactional database is required.");
  const publication = await db.transaction(async (tx) => {
    await tx.query("SELECT pg_advisory_xact_lock(hashtext('yor-publication'))");
    const rows = await tx.query("SELECT snapshot FROM public.publication_history WHERE revision=$1 ORDER BY created_at DESC LIMIT 1", [targetRevision]);
    const target = rows.rows[0] ? PublicationSchema.parse(rows.rows[0]["snapshot"]) : targetRevision === approvedPublication.revision ? approvedPublication : null;
    if (!target) throw new ContentValidationError("Rollback target does not exist.");
    await validatePublicationContent(target,tx);
    const current = await readDurablePublication(tx);
    const next = { ...target,revision: current.revision + 1,publishedAt: new Date().toISOString() };
    await writeSnapshot(tx,next,actor,targetRevision);
    return next;
  });
  const refreshed = await handleCacheRefresh(publication);
  return { ...publication,cacheRefreshed: refreshed.refreshed,...(refreshed.error ? { cacheRefreshWarning: refreshed.error } : {}) };
}

/**
 * YOR WORLD Milestone A4: Server-side Project Revisions & Draft State
 *
 * Implements structured project draft editing, optimistic concurrency control,
 * revision incrementing, and private draft storage.
 */

import {
  type ProjectId,
  type PublishedProject,
  PublishedProjectSchema,
} from "@/contracts/content";
import type { OwnerContext } from "../auth/types";
import { approvedPublication } from "@/content/approved-publication";
import { getPlatformDb, hasPlatformDatabase, isTestRuntime } from "../database";
import type { QueryableDb } from "../contact/quota";

export class RevisionConflictError extends Error {
  readonly status = 409;
  readonly code = "STALE_REVISION_CONFLICT";

  constructor(message: string) {
    super(message);
    this.name = "RevisionConflictError";
  }
}

export class ContentValidationError extends Error {
  readonly status = 422;
  readonly code = "INVALID_CONTENT";

  constructor(message: string) {
    super(message);
    this.name = "ContentValidationError";
  }
}

export interface DraftRecord {
  projectId: ProjectId;
  draftRevision: number;
  project: PublishedProject;
  updatedAt: string;
  updatedBy: string;
}

// In-memory test draft registry initialized with approved publication projects
let testDraftRegistry: Map<ProjectId, DraftRecord> | null = null;

function initializeDefaultDrafts(): Map<ProjectId, DraftRecord> {
  const map = new Map<ProjectId, DraftRecord>();
  const now = new Date().toISOString();

  for (const proj of approvedPublication.projects) {
    map.set(proj.id, {
      projectId: proj.id,
      draftRevision: proj.revision,
      project: { ...proj },
      updatedAt: now,
      updatedBy: "system-seed",
    });
  }

  // Also include candidatex as an unpublished draft (revision 1)
  map.set("candidatex", {
    projectId: "candidatex",
    draftRevision: 1,
    project: {
      id: "candidatex",
      slug: "candidatex",
      title: "CandidateX (Draft)",
      summary: "Draft recruitment analytics platform.",
      contribution: "Sole architect and full-stack engineer.",
      sections: [
        {
          id: "overview",
          heading: "Overview",
          blocks: [{ type: "paragraph", text: "Draft analytics platform documentation." }],
        },
      ],
      links: [{ label: "Repository", url: "https://github.com/yorayriniwnl/candidatex", checkedAt: now }],
      evidence: [
        {
          id: "ev-cx-repo",
          kind: "repository",
          url: "https://github.com/yorayriniwnl/candidatex",
          checkedAt: now,
          status: "verified",
          note: "Private repository code review.",
        },
      ],
      revision: 1,
    },
    updatedAt: now,
    updatedBy: "system-seed",
  });

  return map;
}

export function setTestDraftRegistry(registry: Map<ProjectId, DraftRecord> | null) {
  if (!isTestRuntime()) throw new Error("Draft registry injection is test-only.");
  testDraftRegistry = registry;
}

export function getTestDraftRegistry(): Map<ProjectId, DraftRecord> {
  if (!testDraftRegistry) {
    testDraftRegistry = initializeDefaultDrafts();
  }
  return testDraftRegistry;
}

/**
 * Validates project draft content integrity.
 * Throws ContentValidationError (422) if invalid URLs or malformed blocks are encountered.
 */
export function validateDraftContent(data: unknown): PublishedProject {
  const result = PublishedProjectSchema.safeParse(data);
  if (!result.success) {
    throw new ContentValidationError(
      `Content validation failed: ${result.error.issues.map((i) => `${i.path.join(".")}: ${i.message}`).join(", ")}`
    );
  }

  const project = result.data;

  // Enforce HTTPS URLs
  for (const link of project.links) {
    try {
      const url = new URL(link.url);
      if (url.protocol !== "https:") {
        throw new ContentValidationError(
          `Invalid link URL '${link.url}': protocol must be https://`
        );
      }
    } catch (err) {
      if (err instanceof ContentValidationError) throw err;
      throw new ContentValidationError(`Malformed link URL '${link.url}'`);
    }
  }

  for (const ev of project.evidence) {
    if (ev.url) {
      try {
        const url = new URL(ev.url);
        if (url.protocol !== "https:") {
          throw new ContentValidationError(
            `Invalid evidence URL '${ev.url}': protocol must be https://`
          );
        }
      } catch (err) {
        if (err instanceof ContentValidationError) throw err;
        throw new ContentValidationError(`Malformed evidence URL '${ev.url}'`);
      }
    }
  }

  // Validate sections and blocks
  for (const section of project.sections) {
    if (!section.heading || section.heading.trim().length === 0) {
      throw new ContentValidationError(`Section '${section.id}' has empty heading`);
    }
    if (section.blocks.length === 0) {
      throw new ContentValidationError(`Section '${section.id}' must contain at least one content block`);
    }
  }

  return project;
}

/**
 * Retrieves project draft record. Private: requires owner authorization.
 */
export async function getProjectDraft(
  projectId: ProjectId,
  _actor: OwnerContext
): Promise<DraftRecord | null> {
  void _actor;
  if (!isDraftTestRegistryEnabled()) {
    return (await listProjectDrafts(_actor)).find((draft) => draft.projectId === projectId) ?? null;
  }
  const registry = getTestDraftRegistry();
  const record = registry.get(projectId);
  if (record) {
    return { ...record, project: JSON.parse(JSON.stringify(record.project)) };
  }
  return null;
}

/**
 * Lists all project drafts for owner review.
 */
export async function listProjectDrafts(
  _actor: OwnerContext
): Promise<DraftRecord[]> {
  void _actor;
  if (!isDraftTestRegistryEnabled()) {
    const db = await getPlatformDb();
    return readDurableDrafts(db);
  }
  const registry = getTestDraftRegistry();
  return Array.from(registry.values()).map((r) => ({
    ...r,
    project: JSON.parse(JSON.stringify(r.project)),
  }));
}

/**
 * Saves a modified draft revision using optimistic concurrency control.
 * Stale expectedRevision returns 409 Conflict.
 * Invalid content returns 422 Unprocessable Entity.
 */
export async function saveProjectDraft(
  input: {
    projectId: ProjectId;
    expectedRevision: number;
    project: Omit<PublishedProject, "revision">;
  },
  actor: OwnerContext
): Promise<{ draftRevision: number; project: PublishedProject }> {
  if (input.project.id !== input.projectId || input.project.slug !== input.projectId) {
    throw new ContentValidationError("Draft identity does not match requested project.");
  }
  if (!isDraftTestRegistryEnabled()) return saveDurableDraft(input, actor);
  const registry = getTestDraftRegistry();
  const existing = registry.get(input.projectId);

  const currentRevision = existing ? existing.draftRevision : 0;

  // Optimistic concurrency check
  if (currentRevision !== input.expectedRevision) {
    throw new RevisionConflictError(
      `Stale revision conflict on project '${input.projectId}': expected revision ${input.expectedRevision}, but current revision is ${currentRevision}. Refresh before saving.`
    );
  }

  const nextRevision = currentRevision + 1;
  const projectWithRev: PublishedProject = {
    ...input.project,
    revision: nextRevision,
  };

  // Content validation (throws 422 if invalid)
  const validatedProject = validateDraftContent(projectWithRev);

  const updatedRecord: DraftRecord = {
    projectId: input.projectId,
    draftRevision: nextRevision,
    project: validatedProject,
    updatedAt: new Date().toISOString(),
    updatedBy: actor.userId,
  };

  registry.set(input.projectId, updatedRecord);

  return {
    draftRevision: nextRevision,
    project: validatedProject,
  };
}

export function isDraftTestRegistryEnabled(): boolean {
  return isTestRuntime() && !hasPlatformDatabase();
}

export async function readDurableDrafts(db: QueryableDb): Promise<DraftRecord[]> {
  const result = await db.query(`SELECT p.slug, p.draft_revision, r.payload, r.created_at, r.created_by
    FROM public.projects p JOIN public.project_revisions r
      ON r.project_id=p.id AND r.revision=p.draft_revision WHERE p.archived_at IS NULL`);
  const drafts = new Map<ProjectId, DraftRecord>();
  for (const project of approvedPublication.projects) {
    drafts.set(project.id, { projectId: project.id, draftRevision: project.revision, project,
      updatedAt: approvedPublication.publishedAt, updatedBy: "accepted-static-baseline" });
  }
  for (const row of result.rows) {
    const project = validateDraftContent(row["payload"]);
    drafts.set(project.id, { projectId: project.id, draftRevision: Number(row["draft_revision"]), project,
      updatedAt: new Date(String(row["created_at"])).toISOString(), updatedBy: String(row["created_by"]) });
  }
  return [...drafts.values()];
}

async function saveDurableDraft(input: {
  projectId: ProjectId; expectedRevision: number; project: Omit<PublishedProject, "revision">;
}, actor: OwnerContext): Promise<{ draftRevision: number; project: PublishedProject }> {
  const db = await getPlatformDb();
  if (!db.transaction) throw new Error("Transactional database is required.");
  return db.transaction(async (tx) => {
    await tx.query("SELECT pg_advisory_xact_lock(hashtext($1))", [`yor-draft-${input.projectId}`]);
    const rows = await tx.query("SELECT id,draft_revision FROM public.projects WHERE slug=$1 FOR UPDATE", [input.projectId]);
    let row = rows.rows[0];
    const baseline = approvedPublication.projects.find((project) => project.id === input.projectId);
    const currentRevision = row ? Number(row["draft_revision"]) : (baseline?.revision ?? 0);
    if (currentRevision !== input.expectedRevision) throw new RevisionConflictError("Draft changed. Refresh before saving.");
    const nextRevision = currentRevision + 1;
    const project = validateDraftContent({ ...input.project, revision: nextRevision });
    if (!row) {
      row = (await tx.query("INSERT INTO public.projects(slug,title,draft_revision) VALUES($1,$2,$3) RETURNING id", [input.projectId, project.title, nextRevision])).rows[0]!;
    } else {
      await tx.query("UPDATE public.projects SET title=$1,draft_revision=$2 WHERE id=$3", [project.title,nextRevision,row["id"]]);
    }
    await tx.query("INSERT INTO public.project_revisions(project_id,revision,payload,created_by) VALUES($1,$2,$3,$4)", [row["id"],nextRevision,JSON.stringify(project),actor.userId]);
    await tx.query("INSERT INTO public.audit_events(actor,action,entity_type,entity_id,payload) VALUES($1,'draft_saved','project',$2,$3)", [actor.userId,input.projectId,JSON.stringify({ revision: nextRevision })]);
    return { draftRevision: nextRevision, project };
  });
}

/**
 * YOR WORLD Milestone A4: Media Manifest & Publication Integrity Checker
 *
 * Verifies that all media assets referenced in publication sections exist
 * and hold verified 'approved' status before entering public snapshots.
 */

import type { Publication } from "@/contracts/content";
import { getTestMediaRegistry, MediaValidationError } from "./validate-upload";
import { isDraftTestRegistryEnabled } from "../content/revisions";
import { getPlatformDb } from "../database";
import { createAdminServiceRoleClient } from "../auth/clients";
import { readPublicPublication } from "../content/publish";
import { validatePublication } from "@/content/publication-reader";
import { approvedPublication } from "@/content/approved-publication";
import type { QueryableDb } from "../contact/quota";


export interface MediaCheckResult {
  approved: boolean;
  unapprovedIds: string[];
}

/**
 * Checks a list of media IDs to verify they exist and are approved.
 */
export async function checkMediaApproved(mediaIds: string[], transaction?: QueryableDb): Promise<MediaCheckResult> {
  if (mediaIds.length === 0) {
    return { approved: true, unapprovedIds: [] };
  }

  const uniqueIds = Array.from(new Set(mediaIds));
  const testRegistry = !transaction && isDraftTestRegistryEnabled() ? getTestMediaRegistry() : null;

  if (testRegistry) {
    const unapproved: string[] = [];
    for (const id of uniqueIds) {
      const asset = testRegistry.get(id);
      if (!asset || asset.approvalStatus !== "approved") {
        unapproved.push(id);
      }
    }
    return {
      approved: unapproved.length === 0,
      unapprovedIds: unapproved,
    };
  }

  try {
    const db=transaction ?? await getPlatformDb();
    const { rows } = await db.query("SELECT id,approval_status FROM public.media_assets WHERE id::text = ANY($1::text[])" + (transaction ? " FOR SHARE" : ""),[uniqueIds]);
    const approvedSet = new Set(rows.filter((row) => row["approval_status"] === "approved").map((row) => String(row["id"])));

    const unapproved = uniqueIds.filter((id) => !approvedSet.has(id));
    return {
      approved: unapproved.length === 0,
      unapprovedIds: unapproved,
    };
  } catch {
    // If DB is unreachable and no test registry, check against test registry fallback
    return { approved: false, unapprovedIds: uniqueIds };
  }
}

/**
 * Verifies that all image blocks in a publication snapshot reference approved media.
 * Throws MediaValidationError (422) if unapproved or missing media is detected.
 */
export async function verifyPublicationAssets(publication: Publication, transaction?: QueryableDb): Promise<void> {
  const referencedMediaIds: string[] = [];

  for (const project of publication.projects) {
    for (const section of project.sections) {
      for (const block of section.blocks) {
        if (block.type === "image" && block.mediaId) {
          // Retain the exact accepted honest placeholder; it never resolves to a media URL.
          const acceptedPlaceholder = block.mediaId.startsWith("missing-") && approvedPublication.projects
            .flatMap((item) => item.sections.flatMap((section) => section.blocks))
            .some((accepted) => accepted.type === "image" && JSON.stringify(accepted) === JSON.stringify(block));
          if (acceptedPlaceholder) continue;
          referencedMediaIds.push(block.mediaId);
        }
      }
    }
  }

  if (referencedMediaIds.length === 0) {
    return;
  }

  const check = await checkMediaApproved(referencedMediaIds, transaction);
  if (!check.approved) {
    throw new MediaValidationError(
      `Publication rejected: contains unapproved or missing media assets: [${check.unapprovedIds.join(", ")}]. All media must be verified and approved before publication.`
    );
  }
}

/** Public pages receive URLs only for approved assets referenced by the CURRENT approved snapshot. */
export async function readApprovedPublishedMediaUrls(publication: Publication): Promise<Record<string,string>> {
  try {
    const requested=validatePublication(publication);
    const snapshot=await readPublicPublication();
    if (!snapshot || snapshot.revision !== requested.revision) return {};
    const approved=validatePublication(snapshot);
    const collect=(value: Publication) => new Set(value.projects.filter((project) => project.id !== "candidatex")
      .flatMap((project) => project.sections.flatMap((section) => section.blocks.flatMap((block) => block.type === "image" ? [block.mediaId] : []))));
    const currentIds=collect(approved);
    const wanted=[...collect(requested)].filter((id) => currentIds.has(id) && !id.startsWith("missing"));
    const bucket=process.env.MEDIA_PRIVATE_BUCKET;
    if (!wanted.length || !bucket) return {};
    const db=await getPlatformDb();
    const assets=await db.query("SELECT id,object_key FROM public.media_assets WHERE approval_status='approved' AND id::text=ANY($1::text[])",[wanted]);
    if (!assets.rows.length) return {};
    const signed=await createAdminServiceRoleClient().storage.from(bucket).createSignedUrls(assets.rows.map((row) => String(row["object_key"])),900);
    if (signed.error || !signed.data) return {};
    const byPath=new Map(assets.rows.map((row) => [String(row["object_key"]),String(row["id"])]));
    const urls: Record<string,string>={};
    for (const item of signed.data) {
      if (!item.path || !item.signedUrl || item.error) continue;
      const id=byPath.get(item.path);
      if (id && new URL(item.signedUrl).protocol === "https:") urls[id]=item.signedUrl;
    }
    return urls;
  } catch { return {}; }
}
